//! The project's own logo (`assets/logo/`, original artwork, no game data): the app icon and
//! the station-board header, embedded so the game needs no files for them. The embedded files
//! are generated by `scripts/build-logo.sh`; the pixels are packed RGBA
//! ([`shuppatsu_render::rgba`]), so no image decoder is needed.

use shuppatsu_render::rgba::RgbaImage;
use shuppatsu_render::sprites::WidgetImage;
use std::sync::{Arc, OnceLock};

macro_rules! logo_file {
    ($name:literal) => {
        include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../assets/logo/gen/",
            $name
        ))
    };
}

/// The app icon as PNG files for the hicolor theme, `(size, png)`; 16 and 32 are the
/// hand-hinted drawings.
pub const ICON_PNGS: [(u32, &[u8]); 7] = [
    (16, logo_file!("icon-16.png")),
    (32, logo_file!("icon-32.png")),
    (48, logo_file!("icon-48.png")),
    (64, logo_file!("icon-64.png")),
    (128, logo_file!("icon-128.png")),
    (256, logo_file!("icon-256.png")),
    (512, logo_file!("icon-512.png")),
];

/// The window icons: `Large` 256 px (taskbars, docks, Alt-Tab), `Small` the hinted 32 px
/// (title bars).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IconSize {
    Large,
    // Only Windows has a separate title-bar icon.
    #[cfg_attr(not(windows), allow(dead_code))]
    Small,
}

/// The app icon's pixels.
pub fn icon(size: IconSize) -> RgbaImage {
    let packed: &[u8] = match size {
        IconSize::Large => logo_file!("icon-256.shpk"),
        IconSize::Small => logo_file!("icon-32.shpk"),
    };
    RgbaImage::unpack(packed).expect("the embedded icon is valid (logo tests)")
}

/// The header board's pixels ([`board`]), for screens drawn before any game data exists
/// (the setup screen, crate::setup).
pub fn board_rgba() -> RgbaImage {
    RgbaImage::unpack(logo_file!("board.shpk")).expect("the embedded board is valid (logo tests)")
}

/// The header board (the dark variant without backdrop or posts), 1232×264: four times its
/// 308×66 place in the 640×480 design, so it is drawn 1:1 at the largest UI scale and
/// area-averaged below. Partly transparent edges are flattened onto black, the screens behind
/// it. Decoded once.
pub fn board() -> Arc<WidgetImage> {
    static BOARD: OnceLock<Arc<WidgetImage>> = OnceLock::new();
    BOARD
        .get_or_init(|| {
            let image = RgbaImage::unpack(logo_file!("board.shpk"))
                .expect("the embedded board is valid (logo tests)");
            Arc::new(WidgetImage::new(image, Some([0, 0, 0])))
        })
        .clone()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_images_decode() {
        let large = icon(IconSize::Large);
        assert_eq!((large.width, large.height), (256, 256));
        let small = icon(IconSize::Small);
        assert_eq!((small.width, small.height), (32, 32));
        // Rounded corners: the top left pixel is transparent, the centre opaque.
        assert_eq!(large.rgba[3], 0);
        assert_eq!(large.rgba[(128 * 256 + 128) * 4 + 3], 255);
        let b = board();
        assert_eq!((b.image.width, b.image.height), (1232, 264));
        assert_eq!(
            b.image.width * 66,
            b.image.height * 308,
            "the design's aspect"
        );
    }

    /// build.rs links the icon resource into every windows-gnu binary of this package, this
    /// test binary included.
    #[cfg(all(windows, target_env = "gnu"))]
    #[test]
    fn exe_has_the_icon_resource() {
        use shuppatsu_formats::icon::{IconData, exe_icons};
        let bytes = std::fs::read(std::env::current_exe().unwrap()).unwrap();
        let exe = shuppatsu_formats::exe::Exe::parse(&bytes).unwrap();
        let icons = exe_icons(&exe).unwrap();
        let sizes: Vec<_> = icons.iter().map(|i| i.entry.width).collect();
        assert_eq!(sizes, [16, 32, 48, 256]);
        assert!(icons.iter().all(|i| matches!(i.data, IconData::Png(_))));
    }

    #[test]
    fn pngs_have_their_sizes() {
        for (size, png) in ICON_PNGS {
            assert_eq!(&png[..8], b"\x89PNG\r\n\x1a\n");
            // IHDR width and height, big-endian.
            assert_eq!(png[16..20], size.to_be_bytes());
            assert_eq!(png[20..24], size.to_be_bytes());
        }
    }
}
